        if memo[i][j] is not None:
            return memo[i][j]

        if j == len(pattern):
            result = i == len(text)
        else:
            first_match = i < len(text) and (pattern[j] == text[i] or pattern[j] == '.')

            if j + 1 < len(pattern) and pattern[j + 1] in '*+':
                if pattern[j + 1] == '*':
                    result = (is_match(i, j + 2) or 
                               (first_match and is_match(i + 1, j)))
                else:  # pattern[j + 1] == '+'
                    result = first_match and is_match(i + 1, j)
            else:
                result = first_match and is_match(i + 1, j + 1)

        memo[i][j] = result
